-- Membership is managed out-of-band; users can neither grant nor change their role.
create table public.cms_editors (
  email text primary key check (email = lower(email)),
  created_at timestamptz not null default now()
);
alter table public.cms_editors enable row level security;
revoke all on public.cms_editors from anon, authenticated;
grant select on public.cms_editors to authenticated;
create policy editor_can_read_own_membership on public.cms_editors
  for select to authenticated
  using (email = (select auth.jwt()->>'email') and (select auth.uid()) is not null);

-- Column grants prevent anonymous callers from selecting draft content at all.
create table public.cms_pages (
  slug text primary key check (slug in ('home', 'privacy', 'terms')),
  draft_content jsonb not null check (jsonb_typeof(draft_content) = 'object' and octet_length(draft_content::text) <= 150000),
  published_content jsonb not null check (jsonb_typeof(published_content) = 'object' and octet_length(published_content::text) <= 150000),
  revision integer not null default 1 check (revision > 0),
  updated_at timestamptz not null default now(),
  published_at timestamptz not null default now(),
  updated_by uuid references auth.users(id) on delete set null
);
alter table public.cms_pages enable row level security;
revoke all on public.cms_pages from anon, authenticated;
grant select (slug, published_content, published_at) on public.cms_pages to anon;
grant select, update on public.cms_pages to authenticated;
create policy public_can_read_published_columns on public.cms_pages
  for select to anon using (true);
create policy editors_can_read_pages on public.cms_pages
  for select to authenticated using (
    exists (select 1 from public.cms_editors where email = (select auth.jwt()->>'email'))
  );
create policy editors_can_update_pages on public.cms_pages
  for update to authenticated using (
    exists (select 1 from public.cms_editors where email = (select auth.jwt()->>'email'))
  ) with check (
    exists (select 1 from public.cms_editors where email = (select auth.jwt()->>'email'))
  );

comment on table public.cms_pages is 'Fixed public pages: private drafts and separately published Persian copy.';

-- Publish the existing public copy as the initial version.
insert into public.cms_pages (slug, draft_content, published_content) values
('home','{"eyebrow":"همراه یک شروع تازه، با یارگشت","description":"برای یک فرصت تازه، لازم نیست مسیر را تنها بروید. از شناخت لاتاری تا آماده‌سازی و بررسی درخواست، قدم‌به‌قدم همراه شما هستیم.","step1":"از آشنایی شروع می‌کنیم","step2":"نام و اطلاعات تماس را وارد می‌کنید و شیوه همراهی را انتخاب می‌کنید. برای شروع، همین کافی است.","step3":"با یک مسیر روشن ادامه می‌دهیم","step4":"پس از پرداخت تأییدشده هزینه خدمات، فرم تکمیلی و راهنمای آماده‌سازی مدارک در اختیار شماست.","step5":"جزئیات را با دقت بررسی می‌کنیم","step6":"متخصص، اطلاعات و مدارک را بررسی می‌کند. اگر چیزی نیاز به اصلاح داشته باشد، قدم بعد را با هم برمی‌داریم.","step7":"تا ثبت نهایی، کنارتان می‌مانیم","step8":"ثبت رسمی در بازه اعلام‌شده و پس از تکمیل پرونده انجام می‌شود؛ دریافت درخواست خدمات، به معنی ثبت نهایی نیست.","text1":"رفتن به محتوای اصلی","text2":"هر شروع تازه،","text3":"از","text4":"یک قدم","text5":"آغاز می‌شود","text6":"اولین قدم را بردارید","text7":"اول، بیشتر بدانیم","text8":"بررسی توسط متخصص","text9":"آنلاین و حضوری","text10":"فصل اول","text11":"یک تصمیم تازه","text12":"دارای مجوز گردشگری","text13":"پشتیبانی ۲۴/۷","text14":"دفتر در زعفرانیه","text15":"بررسی دقیق مدارک","text16":"قصه از کجا شروع می‌شود؟","text17":"گاهی یک فرصت،","text18":"مسیر تازه‌ای پیش روی ما می‌گذارد.","text19":"لاتاری گرین‌کارت، فرصتی برای قدم گذاشتن در یک مسیر تازه است؛ اما قدم اول، شناخت درست آن است.","text20":"برنامه Diversity Visa یا DV، مسیر انتخاب متقاضیان برای ادامه فرایند ویزای تنوع آمریکاست. انتخاب شدن، آغاز بررسی پرونده است و به‌تنهایی به معنی دریافت ویزا نیست.","text21":"ما در","text22":"برای تصمیم شما وعده نمی‌سازیم؛ کمک می‌کنیم اطلاعات، مدارک و مراحل درخواست را با دقت بیشتری پیش ببرید.","text23":"آشنایی با برنامه در منبع رسمی","text24":"، در صفحه جدید","text25":"مسیر شما، قدم‌به‌قدم","text26":"مسیر تازه است.","text27":"اما تنها نیستید.","text28":"قرار نیست از همان ابتدا همه‌چیز را بدانید. مسیر را به قدم‌های کوچک و روشن تقسیم کرده‌ایم.","text29":"شما تصمیم می‌گیرید.","text30":"ما همراه مسیر می‌مانیم.","text31":"از اینجا شروع کنیم","text32":"جزئیات کوچک، اهمیت بزرگ","text33":"تصویر راهنما؛ مدرک واقعی نیست","text34":"آماده‌سازی با راهنمای متخصص","text35":"کمی دقت، خیال راحت‌تر","text36":"مدارک درست،","text37":"یک قدم محکم‌تر.","text38":"هر مدرک، راهنمای خودش را دارد. در مرحله تکمیلی، دقیقاً می‌دانید چه چیزی لازم است و چطور باید آماده‌اش کنید.","text39":"عکس، با راهنمای همان دوره","text40":"ویژگی‌های عکس بر اساس دستورالعمل رسمی بررسی می‌شود؛ کنترل فایل، جای بررسی متخصص را نمی‌گیرد.","text41":"اطلاعات کامل، در زمان مناسب","text42":"ابتدا فقط اطلاعات تماس؛ جزئیات و مدارک هویتی در مرحله تکمیلی و از مسیر تعیین‌شده دریافت می‌شوند.","text43":"با احترام به اطلاعات شخصی شما","text44":"قبل از دریافت مدارک، روش ارسال و شرایط نگهداری آن‌ها روشن خواهد بود.","text45":"برای فصل‌های بعدی زندگی","text46":"همراهی، ادامه دارد.","text47":"این داستان می‌تواند ادامه داشته باشد","text48":"اگر انتخاب شدید،","text49":"قدم بعد را هم می‌شناسیم.","text50":"پس از انتخاب شدن در لاتاری، مسیر تازه‌ای از بررسی و تکمیل پرونده آغاز می‌شود. امکان همراهی متخصص برای این مرحله هم وجود دارد.","text51":"این خدمت با بررسی شرایط، دامنه و هزینه جداگانه ارائه می‌شود. انتخاب شدن یا همراهی متخصص، تضمین صدور ویزا نیست.","text52":"با هم مسیر را شروع کنیم","text53":"قبل از اولین قدم","text54":"شاید سؤال شما","text55":"هم همین باشد.","text56":"پاسخ‌های روشن، برای تصمیمی آگاهانه‌تر.","text57":"همراهی واقعی،","text58":"از شنیدن سؤال‌های شما شروع می‌شود.","text59":"یک تصمیم کوچک، یک فصل تازه","text60":"قدم اول، از همین‌جا.","text61":"مسیر را بشناسید، شیوه همراهی را انتخاب کنید.","text62":"انتخاب شیوه همراهی","text63":"بازگشت به بالا","text64":"ارائه‌دهنده مستقل خدمات است و وابستگی به دولت آمریکا ندارد. تعرفه‌های نمایش‌داده‌شده مربوط به خدمات شرکت است؛ هزینه احتمالی رسمی و خدمات بعدی، در صورت لزوم جداگانه اعلام می‌شوند.","text65":"حریم خصوصی","text66":"شرایط خدمات","text67":"منبع رسمی DV","text68":"، در صفحه جدید","faqQuestion1":"آیا پیش‌ثبت‌نام، همان ثبت‌نام رسمی لاتاری است؟","faqAnswer1":"خیر. پیش‌ثبت‌نام، درخواست استفاده از خدمات یارگشت است. ثبت در سامانه رسمی تنها در بازه اعلام‌شده و پس از تکمیل و بررسی اطلاعات انجام می‌شود. دریافت فرم یا پرداخت به معنی ثبت نهایی نیست.","faqQuestion2":"برای شروع چه اطلاعاتی لازم است؟","faqAnswer2":"فقط نام، نام خانوادگی، ایمیل و شماره تماس. پس از پرداخت تأییدشده، فرم تکمیلی و راهنمای مدارک در اختیار شما قرار می‌گیرد. اطلاعات بیشتر را در همان مرحله دریافت می‌کنیم.","faqQuestion3":"تفاوت خدمات آنلاین و حضوری چیست؟","faqAnswer3":"در روش آنلاین، راهنمایی و پیگیری از طریق تماس و پیام‌رسان است. در روش حضوری، متخصص برای بررسی و اسکن مدارک همراه شماست. عکاسی با هماهنگی و توافق جداگانه امکان‌پذیر است.","faqQuestion4":"آیا پرداخت هزینه، شانس برنده‌شدن را بیشتر می‌کند؟","faqAnswer4":"خیر. هزینه خدمات برای آماده‌سازی، بررسی و پیگیری درخواست شماست و احتمال انتخاب شدن را افزایش نمی‌دهد. انتخاب در لاتاری و دریافت ویزا دو مرحله جدا هستند و هیچ‌کدام تضمین نمی‌شوند.","faqQuestion5":"قوانین پاسپورت، عکس و هزینه رسمی را از کجا ببینم؟","faqAnswer5":"مبنای این موارد، دستورالعمل رسمی همان دوره در وب‌سایت وزارت خارجه آمریکاست. تا تأیید اطلاعیه دوره جدید، درباره الزام پاسپورت، مبلغ رسمی یا تاریخ شروع ادعای قطعی نداریم.","faqQuestion6":"اگر انتخاب شدم، باز هم همراه من هستید؟","faqAnswer6":"امکان همراهی متخصص برای مراحل بعد از انتخاب شدن وجود دارد. جزئیات، حدود مسئولیت و هزینه این خدمت جداگانه بررسی و توافق می‌شود؛ این خدمت در تعرفه اولیه ثبت‌نام منظور نشده است."}'::jsonb,'{"eyebrow":"همراه یک شروع تازه، با یارگشت","description":"برای یک فرصت تازه، لازم نیست مسیر را تنها بروید. از شناخت لاتاری تا آماده‌سازی و بررسی درخواست، قدم‌به‌قدم همراه شما هستیم.","step1":"از آشنایی شروع می‌کنیم","step2":"نام و اطلاعات تماس را وارد می‌کنید و شیوه همراهی را انتخاب می‌کنید. برای شروع، همین کافی است.","step3":"با یک مسیر روشن ادامه می‌دهیم","step4":"پس از پرداخت تأییدشده هزینه خدمات، فرم تکمیلی و راهنمای آماده‌سازی مدارک در اختیار شماست.","step5":"جزئیات را با دقت بررسی می‌کنیم","step6":"متخصص، اطلاعات و مدارک را بررسی می‌کند. اگر چیزی نیاز به اصلاح داشته باشد، قدم بعد را با هم برمی‌داریم.","step7